mapper.update:
UPDATE person_employment
SET ended_at = #{endedAt}
WHERE workspace_id = #{workspaceId} AND person_id = #{personId} AND ended_at IS NULL

mapper.select:
SELECT id, workspace_id, person_id, company_id, company_name, title, started_at, ended_at, created_at
FROM person_employment
WHERE workspace_id = #{workspaceId}
